duk::rhi::ShaderModule::Mask PhongShaderDataSource::module_mask() const {
    return duk::rhi::ShaderModule::VERTEX | duk::rhi::ShaderModule::FRAGMENT;
}

const std::vector<uint8_t>& PhongShaderDataSource::shader_module_spir_v_code(duk::rhi::ShaderModule::Bits type) const {
    return kShaderModules.at(type);
}

const std::unordered_map<duk::rhi::ShaderModule::Bits, std::vector<uint8_t>>& PhongShaderDataSource::shader_modules() const {
    return kShaderModules;
}

const duk::rhi::ShaderBindingLayout& PhongShaderDataSource::binding_layout() const {
    return kBindingLayout;
}

const duk::rhi::VertexLayout& PhongShaderDataSource::vertex_layout() const {
    return kVertexLayout;
}

duk::hash::Hash PhongShaderDataSource::calculate_hash() const {
    return static_cast<duk::hash::Hash>(4637861489487086404ULL);
}

